  static int checks;static readonly BindingFlags hidden=BindingFlags.Instance|BindingFlags.NonPublic;
  static void Check(bool value,string text){if(!value)throw new Exception(text);checks++;Console.WriteLine("PASS "+text);}
  static IEnumerable<T> All<T>(DependencyObject p)where T:DependencyObject{if(p is T)yield return(T)p;for(int i=0;i<VisualTreeHelper.GetChildrenCount(p);i++)foreach(var e in All<T>(VisualTreeHelper.GetChild(p,i)))yield return e;}
  static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(150)};timer.Tick+=delegate{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
  static Button Button(OnboardingWindow guide,string name){return All<Button>(guide).Single(b=>b.Name==name);}
  static void Click(OnboardingWindow guide,string name){Button(guide,name).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Button.ClickEvent));Pump();var pet=(PetWindow)typeof(OnboardingWindow).GetField("pet",hidden).GetValue(guide);var saving=(System.Threading.Tasks.Task<bool>)typeof(PetWindow).GetField("explicitSettingsSave",hidden).GetValue(pet);if(saving!=null){var deadline=DateTime.UtcNow.AddSeconds(15);while(!saving.IsCompleted){if(DateTime.UtcNow>deadline)throw new TimeoutException("Guide save");Pump();}saving.GetAwaiter().GetResult();Pump();}}
  static void Go(OnboardingWindow guide,string id){int i=Array.FindIndex(OnboardingLessons.All,l=>l.Id==id);if(i<0)throw new Exception("Missing lesson "+id);typeof(OnboardingWindow).GetField("index",hidden).SetValue(guide,i);typeof(OnboardingWindow).GetMethod("Navigate",hidden).Invoke(guide,null);Pump();}
  static OnboardingWindow Guide(PetWindow pet){return(OnboardingWindow)typeof(PetWindow).GetField("guide",hidden).GetValue(pet);}
  static void Capture(Window window,string name){window.UpdateLayout();string root=Path.Combine(Directory.GetCurrentDirectory(),"work","guide-bookend-evidence");Directory.CreateDirectory(root);var bmp=new RenderTargetBitmap((int)Math.Ceiling(window.ActualWidth),(int)Math.Ceiling(window.ActualHeight),96,96,PixelFormats.Pbgra32);bmp.Render(window);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using(var file=File.Create(Path.Combine(root,name)))png.Save(file);}
  [STAThread]public static int Main(){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};System.Threading.SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext());PetWindow pet=null;try{
   string root=Path.Combine(Directory.GetCurrentDirectory(),"work","guide-bookends-"+Guid.NewGuid().ToString("N"));var cfg=new PetSettings{AutoUpdate=false,GreetingEnabled=false,ReadReplies=false,SaveChatHistory=false,ShowPredictedMessages=false,OnboardingState="new"};foreach(var key in cfg.Hotkeys.Keys.ToArray())cfg.Hotkeys[key]="";pet=new PetWindow(null,cfg,new SettingsStore(Path.Combine(root,"settings.json")),null);pet.ShowOnboarding();Pump();var guide=Guide(pet);var main=app.Windows.OfType<ChatWindow>().Single();
   Check(guide.CurrentLessonId=="language","new guide first asks the user to choose a language");
   var guideHandle=new System.Windows.Interop.WindowInteropHelper(guide).Handle;var area=DesktopInterop.WorkArea(guideHandle);var centered=DesktopInterop.Bounds(guideHandle);Check(!main.IsVisible&&Math.Abs(centered.Left+centered.Width/2-area.Left-area.Width/2)<3&&Math.Abs(centered.Top+centered.Height/2-area.Top-area.Height/2)<3,"guide centers in the work area when no main window is visible");
   var languages=All<ComboBox>(guide).Single(c=>c.Name=="GuideLanguagePicker");Check(languages.Items.Count==UiLanguages.Choices.Count,"language homepage offers every supported language and follow system");
   languages.SelectedValue="en_US";Pump();Check(!All<Button>(guide).Any(b=>b.Name=="GuideRestart")&&Button(guide,"GuideNext").IsEnabled,"restart immediately uses the selected language and changed language requires restart");
   languages.SelectedValue="zh_CN";Pump();Check(Button(guide,"GuideNext").IsEnabled,"unchanged effective language permits continuing without restart");Check(All<TextBlock>(languages).Any(text=>text.Text=="简体中文"),"the selected language renders its native name instead of a CLR type name");
   TextResources.ApplyLanguage(TextResources.PrepareLanguage("en_US"));Pump();Check((string)Button(guide,"GuideNext").Content==TextResources.Get("onboarding.language.applyContinue"),"open language page apply action follows current catalog");TextResources.ApplyLanguage(TextResources.PrepareLanguage("zh_CN"));Pump();
