   main.Width=700;main.Left=30;main.Top=40;Pump();var mainBounds=DesktopInterop.Bounds(new System.Windows.Interop.WindowInteropHelper(main).Handle);var guideBounds=DesktopInterop.Bounds(guideHandle);Check(Math.Abs(guideBounds.Left-Math.Min(mainBounds.Right+12,area.Right-guideBounds.Width))<3,"guide stays against the main window right edge and follows main-window movement");main.Left=area.Right;Pump();guideBounds=DesktopInterop.Bounds(guideHandle);Check(guideBounds.Right<=area.Right+2&&guideBounds.Bottom<=area.Bottom+2,"guide remains on screen when the main window reaches the screen edge");main.Left=30;Pump();
   Go(guide,"network.save");Click(guide,"GuideNext");Check(guide.CurrentLessonId=="update.channel"&&guide.TargetName=="UpdateChannel"&&guide.HighlightVisible,"saved routing leads to the real release-channel selector");
